contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint m, uint a) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(m > 0);
        c.SetMinSum(m); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        uint cEthBefore = address(c).balance;
        uint myEthBefore = address(this).balance;
        bool reverted;
        c.Collect(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted
            && c.balances(address(this)) == balBefore
            && c.MinSum() == minSumBefore
            && address(c).balance == cEthBefore
            && address(this).balance == myEthBefore);
    }
    receive() external payable {}
}

