pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 m, uint256 a) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(m > 0);
        try c.SetMinSum(m) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        uint cEthBefore = address(c).balance;
        uint myEthBefore = address(this).balance;
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted
            && c.balances(address(this)) == balBefore
            && c.MinSum() == minSumBefore
            && address(c).balance == cEthBefore
            && address(this).balance == myEthBefore);
    }

    function testFuzz_run(uint256 m, uint256 a) public {
        _run(m, a);
    }

    receive() external payable {}
}
